const state = { view: 'dashboard', session: null, clients: [], processes: [], tasks: [], documents: [], users: [] };
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const content = $('#content');
const modal = $('#modal');

function esc(value='') { return String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function money(v){ return v == null ? '—' : new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v); }
function date(v){ if(!v) return '—'; const [y,m,d]=v.split('-'); return `${d}/${m}/${y}`; }
function riskClass(r){ return ['Alto','Médio-alto'].includes(r)?'high':r==='Baixo'?'low':'mid'; }
function toast(msg){ const t=$('#toast'); t.textContent=msg; t.classList.add('show'); setTimeout(()=>t.classList.remove('show'),2400); }
async function api(path, options={}){
  const opts={...options,headers:{'Content-Type':'application/json',...(options.headers||{})}};
  const res=await fetch(path,opts); let data={}; try{data=await res.json()}catch{}
  if(res.status===401 && path!=='/api/login'){ showLogin(); throw new Error('Sessão expirada.'); }
  if(!res.ok) throw new Error(data.error||`Erro ${res.status}`); return data;
}
function showLogin(){ $('#appView').classList.add('hidden'); $('#loginView').classList.remove('hidden'); }
function showApp(){ $('#loginView').classList.add('hidden'); $('#appView').classList.remove('hidden'); applyAccess(); }
function applyAccess(){ const role=state.session?.role||''; const usersNav=$('[data-view=users]'); const auditNav=$('[data-view=audit]'); const financeNav=$('[data-view=finance]'); if(usersNav) usersNav.classList.toggle('hidden',role!=='admin'); if(auditNav) auditNav.classList.toggle('hidden',role==='assistant'); if(financeNav) financeNav.classList.toggle('hidden',role==='assistant'); const roleEl=$('#userRole'); if(roleEl) roleEl.textContent=state.session?`${state.session.name} · ${state.session.role}`:'ambiente local'; }

$('#loginForm').addEventListener('submit', async e=>{e.preventDefault(); $('#loginError').textContent=''; const fd=new FormData(e.target); try{const r=await api('/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(fd))}); state.session=r.user; showApp(); await navigate('dashboard');}catch(err){$('#loginError').textContent=err.message;}});
$('#logoutBtn').addEventListener('click',async()=>{await api('/api/logout',{method:'POST'}).catch(()=>{});showLogin();});
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b) navigate(b.dataset.view);});

async function navigate(view){ try{ state.view=view; $$('#nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); const titles={dashboard:'Visão geral',processes:'Processos',agreements:'Acordos',executions:'Execuções',clients:'Clientes',tasks:'Tarefas & Prazos',documents:'Documentos',evidence:'Central de Evidências',preventive:'Trabalhista Preventivo',finance:'Financeiro',reports:'Relatórios',integrations:'Integrações & IA',audit:'Auditoria',users:'Usuários & Perfis'}; $('#pageTitle').textContent=titles[view]||'Central Jurídica'; if(view==='dashboard') return await renderDashboard(); if(view==='processes') return await renderProcesses(); if(view==='agreements') return await renderAgreements(); if(view==='executions') return await renderExecutions(); if(view==='clients') return await renderClients(); if(view==='tasks') return await renderTasks(); if(view==='documents') return await renderDocuments(); if(view==='evidence') return await renderEvidence(); if(view==='preventive') return await renderPreventive(); if(view==='finance') return await renderFinance(); if(view==='reports') return await renderReports(); if(view==='integrations') return await renderIntegrations(); if(view==='users') return await renderUsers(); return await renderAudit(); }catch(err){ toast(err.message); if(view!=='dashboard') return navigate('dashboard'); } }

async function refreshCore(){ const [c,p,t]=await Promise.all([api('/api/clients'),api('/api/processes'),api('/api/tasks')]); state.clients=c.clients;state.processes=p.processes;state.tasks=t.tasks; }

async function renderDashboard(){ const d=await api('/api/dashboard'); content.innerHTML=`<div class="grid stats">${[
['Processos ativos',d.stats.activeProcesses],['Prazos próximos 7 dias',d.stats.deadlinesNext7Days],['Prazos vencidos',d.stats.overdueDeadlines],['Risco elevado',d.stats.highRiskProcesses],['Tarefas pendentes',d.stats.pendingTasks],['Clientes ativos',d.stats.activeClients]
].map(([l,v])=>`<div class="stat"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div><div class="grid two-col"><div class="panel"><h3>O que preciso fazer hoje?</h3><p class="muted">Priorização local por prazo, tarefa e risco. Não depende de IA.</p>${briefList(d.brief?.priorities||[])}</div><div class="panel"><h3>Processos recentes</h3>${processTable(d.recentProcesses)}</div></div>`; bindProcessLinks(); }

function processTable(items){ if(!items.length)return '<div class="empty">Nenhum processo cadastrado.</div>';return `<div class="table-wrap"><table><thead><tr><th>Processo</th><th>Área</th><th>Risco</th><th>Prazo</th><th></th></tr></thead><tbody>${items.map(p=>`<tr><td><strong>${esc(p.title)}</strong><br><small>${esc(p.number||'Sem número')}</small></td><td>${esc(p.area)}</td><td><span class="badge ${riskClass(p.risk)}">${esc(p.risk)}</span></td><td>${date(p.nextDeadline)}</td><td><button class="action-link process-open" data-id="${p.id}">Abrir</button></td></tr>`).join('')}</tbody></table></div>`; }
function taskList(items){if(!items.length)return '<div class="empty">Nenhuma tarefa pendente.</div>';return `<div class="list">${items.map(t=>`<div class="list-item"><strong>${esc(t.title)}</strong><small>${esc(t.priority)} · ${date(t.dueDate)}</small></div>`).join('')}</div>`;}
function briefList(items){if(!items.length)return '<div class="empty">Nenhuma prioridade crítica detectada.</div>';return `<div class="list">${items.slice(0,8).map(x=>`<div class="list-item"><strong><span class="badge ${x.severity==='Crítica'||x.severity==='Alta'?'high':x.severity==='Média'?'mid':'low'}">${esc(x.severity)}</span> ${esc(x.title)}</strong><small>${esc(x.reason)}${x.dueDate?' · '+date(x.dueDate):''}</small></div>`).join('')}</div>`;}

async function renderClients(){ await refreshCore(); content.innerHTML=`<div class="toolbar"><input id="clientSearch" class="search" placeholder="Buscar cliente"><button id="newClient" class="primary">Novo cliente</button></div><div class="panel" id="clientPanel">${clientTable(state.clients)}</div>`; $('#newClient').onclick=openClientForm; $('#clientSearch').oninput=e=>{$('#clientPanel').innerHTML=clientTable(state.clients.filter(c=>c.name.toLowerCase().includes(e.target.value.toLowerCase())))}; }
function clientTable(items){if(!items.length)return '<div class="empty">Nenhum cliente cadastrado.</div>';return `<div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Tipo</th><th>Contato</th><th>Status</th></tr></thead><tbody>${items.map(c=>`<tr><td><strong>${esc(c.name)}</strong><br><small>${esc(c.email)}</small></td><td>${esc(c.type)}</td><td>${esc(c.contact||c.phone||'—')}</td><td><span class="badge">${esc(c.status)}</span></td></tr>`).join('')}</tbody></table></div>`;}
function openClientForm(){ openModal('Novo cliente',`<div class="form-grid"><label>Nome<input name="name" required></label><label>Tipo<select name="type"><option>Empresa</option><option>Pessoa física</option></select></label><label>Contato<input name="contact"></label><label>E-mail<input name="email" type="email"></label><label>Telefone<input name="phone"></label></div>`,async fd=>{await api('/api/clients',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(Object.fromEntries(fd))});toast('Cliente cadastrado.');renderClients();}); }

async function renderProcesses(){ await refreshCore(); content.innerHTML=`<div class="toolbar"><input id="processSearch" class="search" placeholder="Buscar processo, cliente ou número"><button id="newProcess" class="primary" ${state.clients.length?'':'disabled'}>Novo processo</button></div>${state.clients.length?'':'<div class="panel"><p>Cadastre ao menos um cliente antes de criar processos.</p></div>'}<div class="panel" id="processPanel">${processTable(state.processes)}</div>`; $('#newProcess').onclick=openProcessForm; $('#processSearch').oninput=e=>{const q=e.target.value.toLowerCase();$('#processPanel').innerHTML=processTable(state.processes.filter(p=>`${p.title} ${p.number} ${p.clientName}`.toLowerCase().includes(q)));bindProcessLinks();};bindProcessLinks(); }
function bindProcessLinks(){ $$('.process-open').forEach(b=>b.onclick=()=>openProcess(b.dataset.id)); }
function processFields(p={}){return `<div class="form-grid"><label class="wide">Título/identificação<input name="title" value="${esc(p.title||'')}" required></label><label>Nº processo<input name="number" value="${esc(p.number||'')}"></label><label>Cliente<select name="clientId" required>${state.clients.map(c=>`<option value="${c.id}" ${p.clientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Área<select name="area">${['Trabalhista','Cível','Consumidor','Empresarial','Preventivo'].map(v=>`<option ${p.area===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Risco<select name="risk">${['Baixo','Médio-baixo','Médio','Médio-alto','Alto'].map(v=>`<option ${p.risk===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Fase<input name="stage" value="${esc(p.stage||'Análise inicial')}"></label><label>Responsável<input name="owner" value="${esc(p.owner||'')}"></label><label>Próximo prazo<input name="nextDeadline" type="date" value="${esc(p.nextDeadline||'')}"></label><label>Valor pedido<input name="requestedValue" type="number" min="0" step="0.01" value="${p.requestedValue??''}"></label><label>Proposta inicial<input name="agreementInitial" type="number" min="0" step="0.01" value="${p.agreementInitial??''}"></label><label>Teto de acordo<input name="agreementCeiling" type="number" min="0" step="0.01" value="${p.agreementCeiling??''}"></label><label class="wide">Próxima providência<textarea name="nextAction">${esc(p.nextAction||'')}</textarea></label><label class="wide">Fatos relevantes<textarea name="facts">${esc(p.facts||'')}</textarea></label><label class="wide">Tese adversária<textarea name="opposingThesis">${esc(p.opposingThesis||'')}</textarea></label><label class="wide">Nossa tese<textarea name="ourThesis">${esc(p.ourThesis||'')}</textarea></label><label class="wide">Provas/evidências<textarea name="evidence">${esc(p.evidence||'')}</textarea></label><label class="wide">Estratégia<textarea name="strategy">${esc(p.strategy||'')}</textarea></label></div>`;}
function openProcessForm(){ openModal('Novo processo',processFields(),async fd=>{const obj=Object.fromEntries(fd);await api('/api/processes',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(obj)});toast('Processo cadastrado.');renderProcesses();},'Salvar processo'); }
async function openProcess(id){ await refreshCore(); const {process:p,client}=await api(`/api/processes/${id}`); openModal(`${p.title}`,`<div class="grid detail-grid"><div class="panel"><p class="eyebrow">CLIENTE</p><strong>${esc(client?.name||'—')}</strong><p>${esc(p.number||'Sem número')}</p><p><span class="badge ${riskClass(p.risk)}">${esc(p.risk)}</span> · ${esc(p.area)} · ${esc(p.stage)}</p><p><strong>Prazo:</strong> ${date(p.nextDeadline)}<br><strong>Próxima ação:</strong> ${esc(p.nextAction||'—')}</p><p><strong>Valor pedido:</strong> ${money(p.requestedValue)}<br><strong>Proposta inicial:</strong> ${money(p.agreementInitial)}<br><strong>Teto:</strong> ${money(p.agreementCeiling)}</p></div><div class="panel"><p class="eyebrow">MEMÓRIA DO PROCESSO</p><p><strong>Fatos</strong></p><div class="memory">${esc(p.facts||'Não registrado.')}</div><p><strong>Nossa tese</strong></p><div class="memory">${esc(p.ourThesis||'Não registrada.')}</div><p><strong>Estratégia</strong></p><div class="memory">${esc(p.strategy||'Não registrada.')}</div></div></div><div class="modal-actions"><button type="button" class="secondary" id="editProcess">Editar memória</button><button type="button" class="primary" id="auditProcess">Auditar processo</button></div>`,null,null,false); $('#editProcess').onclick=()=>{modal.close();openModal('Editar processo',processFields(p),async fd=>{await api(`/api/processes/${p.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(fd))});toast('Processo atualizado.');renderProcesses();},'Salvar alterações');}; $('#auditProcess').onclick=async()=>{const r=await api(`/api/processes/${p.id}/audit`,{method:'POST'});showAuditResult(p,r.audit);}; }

async function renderTasks(){ await refreshCore(); content.innerHTML=`<div class="toolbar"><div></div><button id="newTask" class="primary">Nova tarefa</button></div><div class="panel">${taskTable(state.tasks)}</div>`; $('#newTask').onclick=openTaskForm; $$('.task-done').forEach(b=>b.onclick=async()=>{await api(`/api/tasks/${b.dataset.id}`,{method:'PATCH',body:JSON.stringify({status:'Concluída'})});toast('Tarefa concluída.');renderTasks();}); }
function taskTable(items){if(!items.length)return '<div class="empty">Nenhuma tarefa cadastrada.</div>';const pm=Object.fromEntries(state.processes.map(p=>[p.id,p.title]));return `<div class="table-wrap"><table><thead><tr><th>Tarefa</th><th>Processo</th><th>Prioridade</th><th>Prazo</th><th>Status</th><th></th></tr></thead><tbody>${items.map(t=>`<tr><td><strong>${esc(t.title)}</strong><br><small>${esc(t.owner||'')}</small></td><td>${esc(pm[t.processId]||'—')}</td><td><span class="badge ${t.priority==='Crítica'||t.priority==='Alta'?'high':t.priority==='Média'?'mid':'low'}">${esc(t.priority)}</span></td><td>${date(t.dueDate)}</td><td>${esc(t.status)}</td><td>${t.status!=='Concluída'?`<button class="action-link task-done" data-id="${t.id}">Concluir</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
function openTaskForm(){openModal('Nova tarefa',`<div class="form-grid"><label class="wide">Descrição<input name="title" required></label><label>Processo<select name="processId"><option value="">Sem vínculo</option>${state.processes.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></label><label>Prioridade<select name="priority"><option>Baixa</option><option selected>Média</option><option>Alta</option><option>Crítica</option></select></label><label>Prazo<input name="dueDate" type="date"></label><label>Responsável<input name="owner"></label></div>`,async fd=>{await api('/api/tasks',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(Object.fromEntries(fd))});toast('Tarefa criada.');renderTasks();});}



async function renderAgreements(){
  await refreshCore(); const r=await api('/api/agreements'); const rows=r.agreements;
  const canWrite=['admin','lawyer'].includes(state.session?.role);
  content.innerHTML=`<div class="toolbar"><div><span class="badge">${rows.length} registro(s)</span></div>${canWrite?'<button id="newAgreement" class="primary">Nova proposta</button>':''}</div><div class="panel"><p class="muted">Histórico de negociação por processo. Valores e mudanças ficam registrados na trilha de auditoria.</p>${agreementTable(rows,canWrite)}</div>`;
  const b=$('#newAgreement'); if(b)b.onclick=()=>openAgreementForm();
  $$('.agreement-edit').forEach(b=>b.onclick=()=>openAgreementForm(rows.find(x=>x.id===b.dataset.id)));
}
function agreementTable(rows,canWrite){if(!rows.length)return '<div class="empty">Nenhuma negociação registrada.</div>';return `<div class="table-wrap"><table><thead><tr><th>Processo</th><th>Movimento</th><th>Valor</th><th>Status</th><th>Data</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td><strong>${esc(a.processTitle)}</strong></td><td>${esc(a.direction)}</td><td>${money(a.amount)}</td><td><span class="badge">${esc(a.status)}</span></td><td>${date(a.occurredAt)}</td><td>${canWrite?`<button class="action-link agreement-edit" data-id="${a.id}">Atualizar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
function openAgreementForm(a=null){
  const p=a||{}; openModal(a?'Atualizar negociação':'Nova proposta',`<div class="form-grid"><label class="wide">Processo<select name="processId" required>${state.processes.map(x=>`<option value="${x.id}" ${p.processId===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label>Movimento<select name="direction"><option ${p.direction==='Nossa proposta'?'selected':''}>Nossa proposta</option><option ${p.direction==='Proposta contrária'?'selected':''}>Proposta contrária</option><option ${p.direction==='Acordo fechado'?'selected':''}>Acordo fechado</option></select></label><label>Valor<input name="amount" type="number" min="0.01" step="0.01" value="${p.amount??''}" required></label><label>Status<select name="status"><option ${p.status==='Em negociação'?'selected':''}>Em negociação</option><option ${p.status==='Aceita'?'selected':''}>Aceita</option><option ${p.status==='Recusada'?'selected':''}>Recusada</option><option ${p.status==='Expirada'?'selected':''}>Expirada</option></select></label><label>Data<input name="occurredAt" type="date" value="${p.occurredAt||''}"></label><label class="wide">Observações<textarea name="notes">${esc(p.notes||'')}</textarea></label></div>`,async fd=>{const body=JSON.stringify(Object.fromEntries(fd));if(a)await api(`/api/agreements/${a.id}`,{method:'PATCH',body});else await api('/api/agreements',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body});toast('Negociação registrada.');renderAgreements();},a?'Salvar':'Registrar');
}

async function renderExecutions(){
  await refreshCore(); const r=await api('/api/executions'); const rows=r.executions; const canWrite=state.session?.role!=='auditor';
  content.innerHTML=`<div class="toolbar"><div><span class="badge">${r.attention.length} revisão(ões) exigindo atenção</span></div>${canWrite?'<button id="newExecution" class="primary">Nova medida</button>':''}</div>${r.attention.length?`<div class="panel"><h3>Revisões próximas/vencidas</h3>${executionAttentionList(r.attention)}</div>`:''}<div class="panel"><p class="muted">Controle operacional de SISBAJUD, RENAJUD, INFOJUD, penhora e demais medidas. O sistema não executa ordens nos tribunais.</p>${executionTable(rows,canWrite)}</div>`;
  const b=$('#newExecution');if(b)b.onclick=()=>openExecutionForm(); $$('.execution-edit').forEach(b=>b.onclick=()=>openExecutionForm(rows.find(x=>x.id===b.dataset.id)));
}
function executionAttentionList(rows){return `<div class="list">${rows.map(x=>`<div class="list-item"><strong><span class="badge ${x.attention==='Vencida'?'high':'mid'}">${esc(x.attention)}</span> ${esc(x.measure)} · ${esc(x.processTitle||'')}</strong><small>Revisão ${date(x.reviewDate)} · ${esc(x.status)}</small></div>`).join('')}</div>`;}
function executionTable(rows,canWrite){if(!rows.length)return '<div class="empty">Nenhuma medida executiva registrada.</div>';return `<div class="table-wrap"><table><thead><tr><th>Processo</th><th>Medida</th><th>Status</th><th>Solicitada</th><th>Revisão</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.processTitle)}</strong></td><td>${esc(x.measure)}</td><td><span class="badge">${esc(x.status)}</span></td><td>${date(x.requestedAt)}</td><td>${date(x.reviewDate)}</td><td>${canWrite?`<button class="action-link execution-edit" data-id="${x.id}">Atualizar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
function openExecutionForm(x=null){
  const p=x||{}; openModal(x?'Atualizar medida executiva':'Nova medida executiva',`<div class="form-grid"><label class="wide">Processo<select name="processId" required>${state.processes.map(q=>`<option value="${q.id}" ${p.processId===q.id?'selected':''}>${esc(q.title)}</option>`).join('')}</select></label><label>Medida<select name="measure">${['SISBAJUD','RENAJUD','INFOJUD','Penhora','Protesto','Intimação','Pesquisa patrimonial','Outra'].map(v=>`<option ${p.measure===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Status<select name="status">${['Planejada','Solicitada','Em andamento','Cumprida','Negativa','Cancelada'].map(v=>`<option ${p.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Data solicitação<input name="requestedAt" type="date" value="${p.requestedAt||''}"></label><label>Revisar em<input name="reviewDate" type="date" value="${p.reviewDate||''}"></label><label class="wide">Resultado<textarea name="result">${esc(p.result||'')}</textarea></label><label class="wide">Observações<textarea name="notes">${esc(p.notes||'')}</textarea></label></div>`,async fd=>{const body=JSON.stringify(Object.fromEntries(fd));if(x)await api(`/api/executions/${x.id}`,{method:'PATCH',body});else await api('/api/executions',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body});toast('Medida executiva registrada.');renderExecutions();},x?'Salvar':'Registrar');
}

async function renderDocuments(){
  await refreshCore();
  const r=await api('/api/documents'); state.documents=r.documents;
  const pm=Object.fromEntries(state.processes.map(p=>[p.id,p.title]));
  const canWrite=state.session?.role!=='auditor';
  content.innerHTML=`<div class="toolbar"><div><span class="badge">${state.documents.length} documento(s)</span></div>${canWrite?'<button id="newDocument" class="primary">Enviar documento</button>':''}</div><div class="panel">${documentTable(state.documents,pm)}</div>`;
  const b=$('#newDocument'); if(b)b.onclick=openDocumentForm;
}
function documentTable(items,pm){ if(!items.length)return '<div class="empty">Nenhum documento cadastrado.</div>'; return `<div class="table-wrap"><table><thead><tr><th>Documento</th><th>Processo</th><th>Tamanho</th><th>SHA-256</th><th></th></tr></thead><tbody>${items.map(d=>`<tr><td><strong>${esc(d.name)}</strong><br><small>${esc(d.mimeType)}</small></td><td>${esc(pm[d.processId]||'Sem vínculo')}</td><td>${formatBytes(d.size)}</td><td><code>${esc(d.sha256.slice(0,16))}…</code></td><td><a class="action-link" href="/api/documents/${d.id}/content">Baixar</a></td></tr>`).join('')}</tbody></table></div>`; }
function formatBytes(n){ if(n<1024)return `${n} B`; if(n<1024*1024)return `${(n/1024).toFixed(1)} KB`; return `${(n/1024/1024).toFixed(1)} MB`; }
function mimeForFile(file){ const ext=file.name.toLowerCase().split('.').pop(); const map={pdf:'application/pdf',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',txt:'text/plain',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png'}; return map[ext]||file.type; }
async function fileToBase64(file){ const bytes=new Uint8Array(await file.arrayBuffer()); let binary=''; const chunk=0x8000; for(let i=0;i<bytes.length;i+=chunk)binary+=String.fromCharCode(...bytes.subarray(i,i+chunk)); return btoa(binary); }
function openDocumentForm(){ openModal('Enviar documento',`<div class="form-grid"><label class="wide">Arquivo<input name="file" type="file" accept=".pdf,.docx,.xlsx,.txt,.jpg,.jpeg,.png" required></label><label class="wide">Processo<select name="processId"><option value="">Sem vínculo</option>${state.processes.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></label><p class="muted wide">Arquivos permitidos: PDF, DOCX, XLSX, TXT, JPG e PNG. Limite: 10 MB. A integridade é registrada por SHA-256.</p></div>`,async fd=>{ const file=fd.get('file'); if(!file?.size)throw new Error('Selecione um arquivo.'); if(file.size>10*1024*1024)throw new Error('Arquivo excede 10 MB.'); const contentBase64=await fileToBase64(file); await api('/api/documents',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({name:file.name,processId:fd.get('processId'),mimeType:mimeForFile(file),contentBase64})}); toast('Documento armazenado com hash de integridade.'); renderDocuments(); },'Enviar'); }






function evidenceDateTime(v){ if(!v)return '—'; try{return new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Asuncion'}).format(new Date(v));}catch{return esc(v);} }
async function renderEvidence(){
  await refreshCore(); const r=await api('/api/evidence'); const items=r.items; const role=state.session?.role||''; const canIngest=role!=='auditor'; const canReview=role==='admin'||role==='lawyer';
  content.innerHTML=`<div class="toolbar"><div><span class="badge">${r.summary.pending} pendente(s)</span> <span class="badge">${r.summary.linked} vinculada(s)</span> <span class="badge">${r.summary.dismissed} descartada(s)</span></div>${canIngest?'<button id="newEvidence" class="primary">Adicionar metadado</button>':''}</div><div class="panel"><h3>Fila de revisão humana</h3><p class="muted">Somente metadados mínimos são armazenados. Corpo de e-mail, conteúdo de arquivos, snippets e anexos são recusados pelo backend.</p>${evidenceTable(items,canReview)}</div>`;
  const b=$('#newEvidence'); if(b)b.onclick=openEvidenceCandidateForm; $$('.evidence-review').forEach(b=>b.onclick=()=>openEvidenceReview(items.find(x=>x.id===b.dataset.id)));
}
function evidenceTable(items,canReview){ if(!items.length)return '<div class="empty">Nenhuma evidência externa na fila.</div>'; return `<div class="table-wrap"><table><thead><tr><th>Fonte</th><th>Metadado</th><th>Data</th><th>Processo</th><th>Status</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td><strong>${esc(x.provider)}</strong><br><small>${esc(x.kind)}</small></td><td>${esc(x.title)}<br><small>hash ${esc((x.metadataHash||'').slice(0,12))}…</small></td><td>${evidenceDateTime(x.occurredAt)}</td><td>${esc(x.processTitle||x.proposedProcessTitle||'—')}${!x.processTitle&&x.proposedProcessTitle?'<br><small>sugerido, não vinculado</small>':''}</td><td><span class="badge">${esc(x.status)}</span></td><td>${canReview&&x.status==='Pendente'?`<button class="action-link evidence-review" data-id="${x.id}">Revisar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`; }
function openEvidenceCandidateForm(){
  openModal('Adicionar metadado externo',`<div class="form-grid"><label>Provedor<select name="provider"><option>Gmail</option><option>Google Calendar</option><option>Google Drive</option></select></label><label>Tipo<select name="kind"><option>E-mail</option><option>Evento</option><option>Arquivo</option></select></label><label class="wide">ID externo<input name="externalId" required placeholder="ID imutável fornecido pelo provedor"></label><label class="wide">Título / assunto<input name="title" required></label><label>Data/hora<input name="occurredAt" type="datetime-local" required></label><label>Processo sugerido<select name="proposedProcessId"><option value="">Sem sugestão</option>${state.processes.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></label><label class="wide">Referência externa opcional<input name="sourceReference" placeholder="URL ou referência opaca; não copie conteúdo"></label><label class="wide">Motivo da sugestão<textarea name="reason" placeholder="Ex.: número do processo no assunto"></textarea></label><p class="muted wide">Não inclua corpo, snippet, texto do arquivo ou anexos. O servidor rejeita esses campos.</p></div>`,async fd=>{const obj=Object.fromEntries(fd);obj.occurredAt=new Date(obj.occurredAt).toISOString();await api('/api/evidence/candidates',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(obj)});toast('Metadado adicionado à fila.');renderEvidence();},'Adicionar à fila');
}
function openEvidenceReview(item){
  const suggested=item.proposedProcessId||''; openModal('Revisar evidência',`<div class="form-grid"><p class="wide"><strong>${esc(item.title)}</strong><br><span class="muted">${esc(item.provider)} · ${esc(item.kind)} · ${evidenceDateTime(item.occurredAt)}</span></p><label>Decisão<select name="decision" id="evidenceDecision"><option>Vincular</option><option>Descartar</option></select></label><label>Processo<select name="processId"><option value="">Selecione</option>${state.processes.map(p=>`<option value="${p.id}" ${p.id===suggested?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label><label class="wide">Nota de revisão<textarea name="reviewNote"></textarea></label><p class="muted wide">A decisão é registrada na trilha de auditoria e torna-se imutável. Vincular não copia o conteúdo externo para o processo.</p></div>`,async fd=>{await api(`/api/evidence/${item.id}/review`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(fd))});toast('Revisão registrada.');renderEvidence();},'Registrar decisão');
}

async function renderPreventive(){
  await refreshCore(); const {assessments}=await api('/api/preventive');
  content.innerHTML=`<div class="toolbar"><button id="newPreventive" class="primary">Nova auditoria preventiva</button></div><div class="panel"><h3>Auditorias trabalhistas preventivas</h3><p class="muted">Checklist estruturado para identificar pontos de atenção e acompanhar plano de ação. Não substitui revisão jurídica profissional.</p>${assessments.length?`<div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Auditoria</th><th>Status</th><th>Completude</th><th>Achados</th><th>Prioridade</th><th>Ações abertas</th><th></th></tr></thead><tbody>${assessments.map(a=>`<tr><td>${esc(a.clientName)}</td><td>${esc(a.title)}<small>${date(a.referenceDate)}</small></td><td>${esc(a.status)}</td><td>${a.summary.completionPercent}%</td><td>${a.summary.findings}</td><td><span class="badge ${riskClass(a.summary.priority==='Crítica'?'Alto':a.summary.priority==='Alta'?'Médio-alto':a.summary.priority==='Média'?'Médio':'Baixo')}">${esc(a.summary.priority)}</span></td><td>${a.summary.openActions}</td><td><button class="link prev-open" data-id="${a.id}">Abrir</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma auditoria preventiva cadastrada.</div>'}</div>`;
  $('#newPreventive').onclick=openPreventiveForm; $$('.prev-open').forEach(b=>b.onclick=()=>openPreventiveAssessment(b.dataset.id));
}

function openPreventiveForm(){
  openModal('Nova auditoria preventiva',`<div class="form-grid"><label>Cliente<select name="clientId" required>${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Data de referência<input name="referenceDate" type="date"></label><label class="wide">Título<input name="title" value="Auditoria Trabalhista Preventiva" required></label><label class="wide">Escopo<textarea name="scope" placeholder="Unidades, áreas, período e documentos analisados"></textarea></label><p class="muted wide">Será criado um checklist padrão com itens de jornada, remuneração, SST, afastamentos, teletrabalho, terceiros, desligamentos e políticas. Os itens começam como “Não verificado”.</p></div>`,async fd=>{await api('/api/preventive',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({...Object.fromEntries(fd),useDefaultTemplate:true})});toast('Auditoria preventiva criada.');renderPreventive();},'Criar checklist');
}

async function openPreventiveAssessment(id){
  const r=await api(`/api/preventive/${id}`), a=r.assessment, s=r.summary;
  const rows=a.items.map(i=>`<tr><td>${esc(i.topic)}<small>${esc(i.question)}</small></td><td>${esc(i.answer)}</td><td>${esc(i.severity)}</td><td>${esc(i.actionStatus)}</td><td>${date(i.dueDate)}</td><td><button class="link prev-item" data-id="${i.id}">Editar</button></td></tr>`).join('');
  openModal(`${a.title}`,`<div class="mini-grid"><div><strong>Completude</strong><span>${s.completionPercent}%</span></div><div><strong>Achados</strong><span>${s.findings}</span></div><div><strong>Alta prioridade</strong><span>${s.highPriorityFindings}</span></div><div><strong>Ações vencidas</strong><span>${s.overdueActions}</span></div><div><strong>Exposição</strong><span>${s.exposureIndex}/100</span></div><div><strong>Prioridade</strong><span>${esc(s.priority)}</span></div></div><p><strong>Cliente:</strong> ${esc(r.client?.name||'—')} · <strong>Status:</strong> ${esc(a.status)}</p><p class="muted">Índice usado apenas para ordenar prioridades operacionais; não é conclusão de conformidade jurídica.</p><div class="table-wrap"><table><thead><tr><th>Tema / verificação</th><th>Resposta</th><th>Severidade</th><th>Ação</th><th>Prazo</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`,null,null,false);
  $$('.prev-item').forEach(b=>b.onclick=()=>{const item=a.items.find(i=>i.id===b.dataset.id);modal.close();openPreventiveItemForm(a,item);});
}

function openPreventiveItemForm(assessment,item){
  openModal(item.topic,`<div class="form-grid"><p class="wide"><strong>${esc(item.question)}</strong></p><label>Resposta<select name="answer">${['Conforme','Parcial','Não conforme','Não se aplica','Não verificado'].map(v=>`<option ${item.answer===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Severidade<select name="severity">${['Baixo','Médio','Alto','Crítico'].map(v=>`<option ${item.severity===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="wide">Evidência<textarea name="evidence">${esc(item.evidence||'')}</textarea></label><label class="wide">Recomendação / plano de ação<textarea name="recommendation">${esc(item.recommendation||'')}</textarea></label><label>Responsável<input name="owner" value="${esc(item.owner||'')}"></label><label>Prazo<input name="dueDate" type="date" value="${item.dueDate||''}"></label><label>Status da ação<select name="actionStatus">${['Aberto','Em andamento','Concluído'].map(v=>`<option ${item.actionStatus===v?'selected':''}>${v}</option>`).join('')}</select></label></div>`,async fd=>{await api(`/api/preventive/${assessment.id}/items/${item.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(fd))});toast('Item preventivo atualizado.');openPreventiveAssessment(assessment.id);},'Salvar item');
}

async function renderFinance(){
  await refreshCore();
  let result;
  try { result=await api('/api/finance'); } catch(err) { content.innerHTML=`<div class="panel"><h3>Financeiro</h3><p class="error">${esc(err.message)}</p></div>`; return; }
  const x=result.summary, entries=result.entries;
  content.innerHTML=`<div class="grid stats">${[
    ['Recebido',money(x.revenueReceived),'Receita efetivamente recebida'],
    ['A receber',money(x.revenuePending),'Receita ainda não realizada'],
    ['Pago',money(x.expensesPaid),'Despesas efetivamente pagas'],
    ['A pagar',money(x.expensesPending),'Despesas ainda não realizadas'],
    ['Caixa realizado',money(x.netCashRealized),'Recebido menos pago'],
    ['Projeção líquida',money(x.projectedNet),'Previstos + realizados, sem cancelados']
  ].map(v=>`<div class="stat-card"><span>${v[0]}</span><strong>${v[1]}</strong><small>${v[2]}</small></div>`).join('')}</div>
  <div class="toolbar"><button id="newFinance" class="primary">Novo lançamento</button></div>
  <div class="panel"><h3>Lançamentos</h3>${entries.length?`<div class="table-wrap"><table><thead><tr><th>Natureza</th><th>Categoria</th><th>Cliente / Processo</th><th>Valor</th><th>Status</th><th>Vencimento</th><th></th></tr></thead><tbody>${entries.map(e=>`<tr><td>${esc(e.direction)}</td><td>${esc(e.category)}</td><td>${esc(e.clientName||'—')}<small>${esc(e.processTitle||'')}</small></td><td>${money(e.amount)}</td><td><span class="badge">${esc(e.status)}</span></td><td>${date(e.dueDate)}</td><td><button class="link finance-edit" data-id="${e.id}">Editar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Sem lançamentos financeiros.</div>'}</div>
  <div class="panel"><h3>Atenção financeira</h3><p class="muted">Somente lançamentos ainda não liquidados e com vencimento em até 7 dias.</p><div class="list">${x.attention.map(e=>`<div class="list-item"><strong>${esc(e.attention)} · ${esc(e.category)} · ${money(e.amount)}</strong><small>${date(e.dueDate)} · ${esc(e.clientName||'')}</small></div>`).join('')||'<div class="empty">Nenhum vencimento próximo.</div>'}</div></div>`;
  $('#newFinance').onclick=()=>openFinanceForm();
  $$('.finance-edit').forEach(b=>b.onclick=()=>openFinanceForm(entries.find(e=>e.id===b.dataset.id)));
}

function openFinanceForm(entry=null){
  const statusesRevenue=['Previsto','Faturado','Recebido','Cancelado'];
  const statusesExpense=['Previsto','A pagar','Pago','Cancelado'];
  const selectedClient=entry?.clientId||state.clients[0]?.id||'';
  const processOptions=()=>state.processes.filter(p=>!selectedClient||p.clientId===selectedClient).map(p=>`<option value="${p.id}" ${entry?.processId===p.id?'selected':''}>${esc(p.title)}</option>`).join('');
  openModal(entry?'Editar lançamento':'Novo lançamento',`<div class="form-grid"><label>Cliente<select name="clientId" id="finClient" required>${state.clients.map(c=>`<option value="${c.id}" ${c.id===selectedClient?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Processo<select name="processId" id="finProcess"><option value="">Sem vínculo</option>${processOptions()}</select></label><label>Natureza<select name="direction" id="finDirection"><option ${entry?.direction==='Receita'?'selected':''}>Receita</option><option ${entry?.direction==='Despesa'?'selected':''}>Despesa</option></select></label><label>Categoria<select name="category">${['Honorários fixos','Honorários de êxito','Custas','Perito','Correspondente','Reembolso','Outros'].map(v=>`<option ${entry?.category===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Valor<input name="amount" type="number" min="0.01" step="0.01" value="${entry?.amount??''}" required></label><label>Status<select name="status" id="finStatus"></select></label><label>Vencimento<input name="dueDate" type="date" value="${entry?.dueDate||''}"></label><label>Liquidação<input name="settledAt" type="date" value="${entry?.settledAt||''}"></label><label class="wide">Descrição<input name="description" value="${esc(entry?.description||'')}"></label><label class="wide">Observações<textarea name="notes">${esc(entry?.notes||'')}</textarea></label><p class="muted wide">Caixa realizado considera apenas receitas recebidas e despesas pagas. Valores previstos não são tratados como dinheiro realizado.</p></div>`,async fd=>{const body=JSON.stringify(Object.fromEntries(fd)); if(entry) await api(`/api/finance/${entry.id}`,{method:'PATCH',body}); else await api('/api/finance',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body}); toast('Lançamento financeiro salvo.'); renderFinance();},entry?'Salvar':'Registrar');
  const clientSel=$('#finClient'), procSel=$('#finProcess'), dirSel=$('#finDirection'), statusSel=$('#finStatus');
  const fillProcesses=()=>{const keep=procSel.value;procSel.innerHTML='<option value="">Sem vínculo</option>'+state.processes.filter(p=>p.clientId===clientSel.value).map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('');if([...procSel.options].some(o=>o.value===keep))procSel.value=keep;};
  const fillStatus=()=>{const list=dirSel.value==='Receita'?statusesRevenue:statusesExpense;statusSel.innerHTML=list.map(v=>`<option ${entry?.status===v?'selected':''}>${v}</option>`).join('');};
  clientSel.onchange=fillProcesses;dirSel.onchange=fillStatus;fillStatus();
}

async function renderReports(){
  await refreshCore();
  content.innerHTML=`<div class="grid two-col"><div class="panel"><h3>Relatório por cliente</h3><p class="muted">Carteira, riscos, tarefas pendentes, valores conhecidos, acordos e execuções.</p><label>Cliente<select id="reportClient"><option value="">Selecione...</option>${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><div class="toolbar" style="margin-top:14px"><button id="viewClientReport" class="primary">Visualizar</button><a id="clientCsv" class="secondary action-link" href="#">Exportar CSV</a></div><div id="clientReportOutput"></div></div><div class="panel"><h3>Relatório por processo</h3><p class="muted">Status consolidado, memória, auditoria local, tarefas, documentos, acordos e medidas executivas.</p><label>Processo<select id="reportProcess"><option value="">Selecione...</option>${state.processes.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></label><button id="viewProcessReport" class="primary" style="margin-top:14px">Visualizar</button><div id="processReportOutput"></div></div></div>`;
  $('#reportClient').onchange=e=>{$('#clientCsv').href=e.target.value?`/api/reports/client/${e.target.value}/export?format=csv`:'#';};
  $('#viewClientReport').onclick=async()=>{const id=$('#reportClient').value;if(!id)return toast('Selecione um cliente.');const r=await api(`/api/reports/client/${id}`);const x=r.report;$('#clientReportOutput').innerHTML=`<div class="mini-grid"><div><strong>Processos</strong><span>${x.summary.processes}</span></div><div><strong>Risco alto</strong><span>${x.summary.highRisk}</span></div><div><strong>Tarefas</strong><span>${x.summary.pendingTasks}</span></div></div><p><strong>Valor pedido conhecido:</strong> ${money(x.summary.requestedValueKnownTotal)} <small>(${x.summary.requestedValueKnownCount} processo(s) com valor)</small></p>${x.finance?`<p><strong>Caixa realizado:</strong> ${money(x.finance.netCashRealized)} · <strong>A receber:</strong> ${money(x.finance.revenuePending)} · <strong>A pagar:</strong> ${money(x.finance.expensesPending)}</p>`:''}${processTable(x.processes.map(p=>({...p,nextDeadline:p.nextDeadline})))}`;bindProcessLinks();};
  $('#viewProcessReport').onclick=async()=>{const id=$('#reportProcess').value;if(!id)return toast('Selecione um processo.');const r=await api(`/api/reports/process/${id}`);const x=r.report;$('#processReportOutput').innerHTML=`<h4>${esc(x.process.title)}</h4><p><span class="badge ${riskClass(x.process.risk)}">${esc(x.process.risk)}</span> <span class="badge">${esc(x.localAudit.decision)}</span></p><div class="mini-grid"><div><strong>Tarefas pendentes</strong><span>${x.tasks.pending}</span></div><div><strong>Documentos</strong><span>${x.documents.total}</span></div><div><strong>Execuções</strong><span>${x.executions.total}</span></div></div><p><strong>Próxima ação:</strong> ${esc(x.process.nextAction||'—')}</p>${x.finance?`<p><strong>Financeiro:</strong> caixa ${money(x.finance.netCashRealized)} · a receber ${money(x.finance.revenuePending)} · a pagar ${money(x.finance.expensesPending)}</p>`:''}<p><strong>Prazo:</strong> ${date(x.process.nextDeadline)}</p><p class="muted">${x.limitations.map(esc).join(' · ')}</p>`;};
}

async function renderIntegrations(){
  await refreshCore();
  const status=await api('/api/integrations/status');
  const role=state.session?.role||'';
  const canOperate=role==='admin'||role==='lawyer';
  content.innerHTML=`
    <div class="grid two-col">
      <div class="panel">
        <h3>Google Workspace</h3>
        <p><span class="badge ${status.google.configured?'low':'mid'}">${status.google.configured?'Configurado':'Não configurado'}</span> <span class="badge">Somente leitura</span></p>
        <p class="muted">Gmail: apenas metadados. Calendar: eventos. Drive: metadados de arquivos. O snapshot não é persistido automaticamente.</p>
        ${canOperate?`<div class="form-grid"><label class="wide">Filtro opcional do Gmail<input id="gmailQuery" placeholder="ex.: newer_than:7d"></label></div><button id="syncGoogle" class="primary" ${status.google.configured?'':'disabled'}>Ler metadados</button> <button id="dailyGoogle" class="secondary" ${status.google.configured?'':'disabled'}>Resumo do dia + Google</button>`:'<p class="muted">Seu perfil possui acesso de leitura ao status, sem permissão de sincronização.</p>'}
        <div id="googleOutput" class="integration-output"></div>
      </div>
      <div class="panel">
        <h3>IA jurídica</h3>
        <p><span class="badge ${status.openai.configured?'low':'mid'}">${status.openai.configured?'Configurada':'Não configurada'}</span>${status.openai.model?` <span class="badge">${esc(status.openai.model)}</span>`:''}</p>
        <p class="muted"><strong>RASCUNHO — REVISÃO HUMANA OBRIGATÓRIA.</strong> A chamada usa <code>store:false</code>; nenhum rascunho é salvo automaticamente na Central Jurídica.</p>
        ${canOperate?`<label>Processo<select id="aiProcess"><option value="">Selecione...</option>${state.processes.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></label><label>Tarefa<select id="aiTask"><option value="analysis">Análise jurídica inicial</option><option value="strategy">Estratégia processual</option><option value="contestacao">Estrutura de contestação</option><option value="impugnacao">Estrutura de impugnação</option><option value="hearing">Preparação para audiência</option></select></label><button id="runAi" class="primary" ${status.openai.configured?'':'disabled'}>Gerar rascunho</button>`:'<p class="muted">Seu perfil não possui permissão para gerar rascunhos com IA.</p>'}
        <div id="aiOutput" class="integration-output"></div>
      </div>
    </div>`;

  const sync=$('#syncGoogle');
  if(sync) sync.onclick=async()=>{
    sync.disabled=true; $('#googleOutput').innerHTML='<p class="muted">Consultando metadados…</p>';
    try{
      const r=await api('/api/integrations/google/snapshot',{method:'POST',body:JSON.stringify({gmailQuery:$('#gmailQuery').value,maxGmail:10,calendarDays:14,maxDrive:20})});
      const x=r.snapshot;
      $('#googleOutput').innerHTML=`<h4>Snapshot somente leitura</h4><p class="muted">${new Date(x.generatedAt).toLocaleString('pt-BR')}</p><div class="mini-grid"><div><strong>Gmail</strong><span>${x.gmail.length}</span></div><div><strong>Agenda</strong><span>${x.calendar.length}</span></div><div><strong>Drive</strong><span>${x.drive.length}</span></div></div>${x.gmail.slice(0,5).map(m=>`<div class="list-item"><strong>${esc(m.subject)}</strong><small>${esc(m.from)} · ${esc(m.date)}</small></div>`).join('')}`;
    }catch(err){ $('#googleOutput').innerHTML=`<p class="error">${esc(err.message)}</p>`; }
    finally{sync.disabled=!status.google.configured;}
  };

  const dailyGoogle=$('#dailyGoogle');
  if(dailyGoogle) dailyGoogle.onclick=async()=>{
    dailyGoogle.disabled=true; $('#googleOutput').innerHTML='<p class="muted">Montando resumo integrado…</p>';
    try{
      const r=await api('/api/brief/daily',{method:'POST',body:JSON.stringify({includeGoogle:true,gmailQuery:$('#gmailQuery').value,maxGmail:10,calendarDays:7})});
      const b=r.brief;
      $('#googleOutput').innerHTML=`<h4>Prioridades integradas</h4>${briefList(b.priorities)}<h4>Possíveis e-mails relacionados</h4><div class="list">${b.emailCorrelations.slice(0,8).map(x=>`<div class="list-item"><strong>${esc(x.subject)}</strong><small>${esc(x.processTitle)} · ${esc(x.reason)} · score ${x.score}</small></div>`).join('')||'<div class="empty">Nenhuma correlação suficientemente forte.</div>'}</div><p class="muted">Correlação é sugestão; nenhum vínculo foi criado.</p>`;
    }catch(err){ $('#googleOutput').innerHTML=`<p class="error">${esc(err.message)}</p>`; }
    finally{dailyGoogle.disabled=!status.google.configured;}
  };

  const run=$('#runAi');
  if(run) run.onclick=async()=>{
    const id=$('#aiProcess').value;if(!id)return toast('Selecione um processo.');
    run.disabled=true; $('#aiOutput').innerHTML='<p class="muted">Gerando rascunho para revisão humana…</p>';
    try{
      const r=await api(`/api/processes/${id}/ai/draft`,{method:'POST',body:JSON.stringify({task:$('#aiTask').value,confirmExternalProcessing:true})});
      $('#aiOutput').innerHTML=`<div class="draft-warning">${esc(r.draft.label)}</div><pre class="draft-output">${esc(r.draft.text)}</pre><p class="muted">${r.draft.limitations.map(esc).join(' · ')}</p>`;
    }catch(err){ $('#aiOutput').innerHTML=`<p class="error">${esc(err.message)}</p>`; }
    finally{run.disabled=!status.openai.configured;}
  };
}

async function renderUsers(){
  const r=await api('/api/users'); state.users=r.users;
  content.innerHTML=`<div class="toolbar"><div><span class="badge">RBAC ativo</span></div><button id="newUser" class="primary">Novo usuário</button></div><div class="panel">${userTable(state.users)}</div>`;
  $('#newUser').onclick=openUserForm;
}
function userTable(items){return `<div class="table-wrap"><table><thead><tr><th>Usuário</th><th>Nome</th><th>Perfil</th><th>Status</th></tr></thead><tbody>${items.map(u=>`<tr><td><strong>${esc(u.username)}</strong></td><td>${esc(u.name)}</td><td><span class="badge">${esc(u.role)}</span></td><td>${u.active===false?'Inativo':'Ativo'}</td></tr>`).join('')}</tbody></table></div>`;}
function openUserForm(){openModal('Novo usuário',`<div class="form-grid"><label>Usuário<input name="username" minlength="3" required></label><label>Nome<input name="name" required></label><label>Perfil<select name="role"><option value="lawyer">Advogado(a)</option><option value="assistant">Assistente</option><option value="auditor">Auditor(a)</option><option value="admin">Administrador(a)</option></select></label><label>Senha temporária<input name="password" type="password" minlength="12" required></label><p class="muted wide">A senha é armazenada somente como hash scrypt. O perfil define as permissões no servidor.</p></div>`,async fd=>{await api('/api/users',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(Object.fromEntries(fd))});toast('Usuário criado.');renderUsers();},'Criar usuário');}

async function renderAudit(){ await refreshCore(); const logs=(await api('/api/audit-log')).auditLog; content.innerHTML=`<div class="grid two-col"><div class="panel"><h3>Auditoria de processo</h3><p class="muted">O motor local verifica prazo, completude da memória, risco e coerência básica de acordo. Nenhum resultado é tratado como decisão jurídica automática.</p><label>Selecione um processo<select id="auditSelect"><option value="">Selecione...</option>${state.processes.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></label><button id="runAudit" class="primary" style="margin-top:14px">Executar auditoria</button><div id="auditOutput" style="margin-top:18px"></div></div><div class="panel"><h3>Trilha de auditoria</h3><div class="list">${logs.slice(0,12).map(l=>`<div class="list-item"><strong>${esc(l.action)} · ${esc(l.entity)}</strong><small>${new Date(l.at).toLocaleString('pt-BR')} · ${esc(l.entityId)}</small></div>`).join('')||'<div class="empty">Sem registros.</div>'}</div></div></div>`; $('#runAudit').onclick=async()=>{const id=$('#auditSelect').value;if(!id)return toast('Selecione um processo.');const p=state.processes.find(x=>x.id===id);const r=await api(`/api/processes/${id}/audit`,{method:'POST'});$('#auditOutput').innerHTML=auditHtml(p,r.audit);}; }
function auditHtml(p,a){return `<div><div class="audit-score">${a.score}</div><div class="audit-decision">${esc(a.decision)}</div><p class="muted">${esc(p.title)}</p>${a.findings.map(f=>`<div class="finding"><span class="badge ${f.severity==='Crítico'||f.severity==='Alto'?'high':f.severity==='Médio'?'mid':'low'}">${esc(f.severity)}</span> <strong>${esc(f.kind)}</strong><div>${esc(f.message)}</div></div>`).join('')}${a.nextActions.length?`<h4>Próximas ações</h4><ul>${a.nextActions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p class="muted"><strong>Limitações:</strong> ${a.limitations.map(esc).join(' · ')}</p></div>`;}
function showAuditResult(p,a){ openModal(`Auditoria — ${p.title}`,auditHtml(p,a),null,null,false); }

function openModal(title,body,onSubmit,submitLabel='Salvar',showFooter=true){ $('#modalBody').innerHTML=`<div class="modal-head"><h3>${esc(title)}</h3><button type="button" id="closeModal" class="secondary">Fechar</button></div><div class="modal-content">${body}</div>${showFooter&&onSubmit?`<div class="modal-actions"><button type="button" id="cancelModal" class="secondary">Cancelar</button><button type="submit" class="primary">${esc(submitLabel)}</button></div>`:''}`; $('#closeModal').onclick=()=>modal.close(); const cancel=$('#cancelModal');if(cancel)cancel.onclick=()=>modal.close(); const form=$('#modalForm'); form.onsubmit=async e=>{e.preventDefault();if(!onSubmit)return;const btn=form.querySelector('[type=submit]');if(btn)btn.disabled=true;try{await onSubmit(new FormData(form));modal.close();}catch(err){toast(err.message);}finally{if(btn)btn.disabled=false;}}; modal.showModal(); }

(async function init(){ try{const r=await api('/api/session');state.session=r.user;showApp();await navigate('dashboard');}catch{showLogin();} })();
